    inset: 0;
    background: rgba(46, 61, 83, 0.65);
    backdrop-filter: blur(4px);
    z-index: var(--z-sticky);
  }

  /* Lock scrolling on html, not body: overflow on body breaks the sticky header */
  :global(html:has(body.menu-open)) {
    overflow: hidden;
